        timestamp = bound(timestamp, 1, type(uint64).max);
        // Set the block number and timestamp for the first call
        vm.roll(blockNum + 1);
        vm.warp(timestamp);
        address sender = address(0x1234);
        // First call to set pastBlockTime
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        c.f{value: 10 ether}();
        // Second call with a later timestamp
