        try c.f{value: 10 ether}() { } catch { }
        uint256 balanceAfter = address(c).balance;
        // After the second call, if the balance was transferred to sender (balanceAfter == 0),
        // the block number used must satisfy (block.number % 15 == 0).
        // This holds for the reference but fails for the mutant.
        assertTrue(balanceAfter > 0 || (blockNum + 2) % 15 == 0);
    }
