pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, uint256 timestampIncrement, uint64 g) public {
        // 1. Keep params in the admissible domain
        vm.assume(timestampIncrement > 0);
        vm.assume(blockNumber > 0);
        vm.assume(g >= 1 && g <= 5);
        // Set up the chain state
        vm.roll(blockNumber);
        vm.warp(1);
        // Make the first call to set pastBlockTime
        address caller = makeAddr("caller");
        vm.deal(caller, 20 ether);
        vm.prank(caller);
        (bool successFirst, ) = address(c).call{value: 10 ether}("");
        vm.assume(successFirst);
        // Warp and roll to the fuzzed state for the deciding call
        vm.roll(blockNumber + 1);
        vm.warp(1 + timestampIncrement);
        // Fund the contract again if needed (none in this scenario, the contract already has 10 ether)
        // But ensure the caller has enough for the second 10 ether call
        uint256 callerBalanceBefore = caller.balance;
        vm.assume(callerBalanceBefore >= 10 ether);
        // 2. Execute the deciding call
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "call failed");
        // 3. Assertion: if the contract balance is zero after the call, then the deciding block number must be divisible by 15
        uint256 contractBalance = address(c).balance;
        if (contractBalance == 0) {
            assertTrue(block.number % 15 == 0);
        } else {
            // Trivially true to maintain the single assert for all inputs
            assertTrue(true);
        }
    }
}

