pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 senderPrivateKey, uint96 blockNumber) public {
        // keep senderPrivateKey in a reasonable range to derive a consistent address
        vm.assume(senderPrivateKey > 0 && senderPrivateKey < 2**256 - 1);
        // derive the sender from the fuzzed private key
        address actor = vm.addr(senderPrivateKey);
        // blockNumber modulus branch: we want the branch to be reachable but let the fuzzer explore
        vm.assume(blockNumber % 15 == 0 && blockNumber > 0);

        uint256 valueAmt = 10 ether;
        // fund the actor
        vm.deal(actor, valueAmt);

        // set block properties so that block.timestamp > pastBlockTime (pastBlockTime initially 0)
        vm.warp(1);
        vm.roll(blockNumber);

        // record balance before the call
        uint256 balanceBefore = address(c).balance;

        vm.prank(actor);
        (bool success, ) = address(c).call{value: valueAmt}("");
        // the fallback may revert if conditions are not met, but the trigger branch was selected
        // we only care about the case where it succeeded and the branch executed.
        vm.assume(success);

        // after a successful fallback where block.number % 15 == 0, the reference transfers the
        // whole balance to msg.sender, leaving 0. The bug transfers to address(0), leaving balance > 0.
        assertTrue(address(c).balance == 0);
    }
}

