        vm.assume(blockNum > 0);
        vm.assume(blockNum % 15 == 0);
        // warp to a future timestamp so require(block.timestamp > pastBlockTime) passes
        vm.warp(warpTime + 1);
        // set block number to the fuzzed value that satisfies the condition
        vm.roll(blockNum);

        // fund the caller and make the call with exactly 10 ether
        address caller = makeAddr("caller");
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "fallback reverted");

        // invariant: after a successful fallback that triggers the transfer branch,
        // the contract's balance must be strictly less than 10 ether.
        // Reference C transfers to msg.sender -> balance becomes 0 < 10 ether.
        // Mutant sends to address(0) which does nothing -> balance remains 10 ether, violating this.
        assertTrue(address(c).balance < 10 ether);
    }
}

