pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 fuzzRoll, address fuzzSender) public {
        // bound roll to a reasonable range and ensure the transfer branch is taken
        uint256 roll = bound(fuzzRoll, 0, 14); // ensures block.number % 15 can be 0 for roll=0
        vm.assume(roll == 0); // force transfer branch
        vm.assume(fuzzSender != address(0));

        // setup: deal ether, set block and call fallback
        vm.deal(fuzzSender, 20 ether);
        vm.prank(fuzzSender);
        vm.roll(15); // block.number % 15 == 0
        vm.warp(1);

        uint256 senderBalanceBefore = fuzzSender.balance;
        c.fallback{value: 10 ether}();
        uint256 senderBalanceAfter = fuzzSender.balance;

        // General rule: if the transfer branch executed, msg.sender received the contract's entire balance.
        // In the reference, sender's balance increases by exactly the contract's balance after the transfer.
        // In the buggy version, address(0) receives the balance, so sender's balance does not increase.
        assertTrue(senderBalanceAfter >= senderBalanceBefore + 10 ether);
    }
}

