import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 firstBlock, uint256 secondBlock) public {
        // Bound block numbers to a reasonable range and ensure monotonic timestamps
        firstBlock = bound(firstBlock, 1, 1_000_000);
        secondBlock = bound(secondBlock, firstBlock + 1, firstBlock + 1_000_000);
        uint256 firstTimestamp = firstBlock;
        uint256 secondTimestamp = secondBlock;

        // Fund a caller
        address caller = address(0x1234);
        vm.deal(caller, 20 ether);

        // First call: set pastBlockTime and possibly drain balance
        vm.roll(firstBlock);
        vm.warp(firstTimestamp);
        vm.prank(caller);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");

        uint256 balanceAfterFirst = address(c).balance;

        // Second call: payout behavior depends on block number
        // Refund caller for second call
        vm.deal(caller, 10 ether);
        vm.roll(secondBlock);
        vm.warp(secondTimestamp);
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        require(ok2, "second call failed");

        uint256 balanceAfterSecond = address(c).balance;

        // Property: the balance after the second call is zero if and only if the second block is a multiple of 15.
        // In the reference, payout occurs exactly when block.number % 15 == 0.
        // In the mutant (modulus 10), the payout condition is block.number % 10 == 0, breaking this equivalence.
        bool isPayoutBlock = (secondBlock % 15 == 0);
        bool contractDrained = (balanceAfterSecond == 0);
        assertTrue(contractDrained == isPayoutBlock);
    }
}

