pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 warpTime1, uint256 warpTime2, uint256 amount, uint256 blockNum) public {
        amount = bound(amount, 1, 10 ether);
        vm.assume(warpTime2 > warpTime1);
        vm.assume(warpTime1 > 0);
        vm.assume(blockNum % 15 != 0);

        vm.warp(warpTime1);
        vm.roll(blockNum);
        vm.deal(address(this), amount);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        require(success1, "first call failed");

        vm.warp(warpTime2);
        vm.deal(address(this), amount);
        (bool success2, ) = address(c).call{value: 10 ether}("");
        require(success2, "second call failed");

        assertEq(c.pastBlockTime(), warpTime2);
    }
}

