pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 ts1, uint256 ts2, uint256 blk1, uint256 blk2) public {
        // Restrict timestamps to a wide admissible range: ts1 < ts2 and both > 0
        vm.assume(ts1 > 0 && ts2 > ts1 && ts2 <= type(uint256).max - 1);
        // Block numbers must satisfy the difference; let them be any value

        // First call
        address sender = makeAddr("sender");
        vm.deal(sender, 20 ether);
        vm.warp(ts1);
        vm.roll(blk1);
        vm.prank(sender);
        c.fallback{value: 10 ether}();

        // Second call
        vm.warp(ts2);
        vm.roll(blk2);
        vm.prank(sender);
        c.fallback{value: 10 ether}();

        // After the second call, pastBlockTime must equal ts2
        assertEq(c.pastBlockTime(), ts2);
    }
}

